import numpy as np
from sklearn.cluster import KMeans

from app.analyzers.base import BaseAnalyzer
from app.models import (
    AnalysisResult,
    DatasetConfig,
    Finding,
)


class ClusteringAnalyzer(BaseAnalyzer):

    @property
    def name(self) -> str:
        return "clustering"

    def analyze(
        self,
        working_dataset,
        config: DatasetConfig,
    ) -> AnalysisResult:

        # Clustering is performed separately using
        # embeddings generated by EmbeddingPipeline.

        return AnalysisResult(
            analyzer=self.name,
            images_checked=0,
            findings=[],
        )

    def process_embeddings(
        self,
        embeddings: np.ndarray,
        image_ids: list[str],
        config: DatasetConfig,
    ) -> AnalysisResult:

        # -----------------------------------------
        # 1. Check whether clustering is enabled
        # -----------------------------------------

        if not config.enable_clustering:

            return AnalysisResult(
                analyzer=self.name,
                images_checked=len(image_ids),
                findings=[],
            )

        # -----------------------------------------
        # 2. Handle empty dataset
        # -----------------------------------------

        if len(embeddings) == 0:

            return AnalysisResult(
                analyzer=self.name,
                images_checked=0,
                findings=[],
            )

        # -----------------------------------------
        # 3. Validate number of clusters
        # -----------------------------------------

        num_clusters = config.num_clusters

        if num_clusters < 1:

            raise ValueError(
                "num_clusters must be at least 1."
            )

        if num_clusters > len(embeddings):

            raise ValueError(
                "num_clusters cannot be greater "
                "than the number of images."
            )

        # -----------------------------------------
        # 4. K-Means
        # -----------------------------------------

        clustering = KMeans(
            n_clusters=num_clusters,
            random_state=42,
            n_init=10,
        )

        cluster_labels = clustering.fit_predict(
            embeddings
        )

        # -----------------------------------------
        # 5. Calculate distance from cluster center
        # -----------------------------------------

        distances = clustering.transform(
            embeddings
        )

        assigned_distances = distances[
            np.arange(len(embeddings)),
            cluster_labels,
        ]

        # -----------------------------------------
        # 6. Calculate threshold
        #
        # Images that are unusually far from
        # their cluster center are suspicious.
        # -----------------------------------------

        distance_threshold = float(
            np.mean(assigned_distances)
            + 2 * np.std(assigned_distances)
        )

        findings = []

        # -----------------------------------------
        # 7. Identify visual outliers
        # -----------------------------------------

        for index, distance in enumerate(
            assigned_distances
        ):

            if distance <= distance_threshold:
                continue

            findings.append(
                Finding(
                    image_id=image_ids[index],
                    issue_type="visual_outlier",
                    severity="medium",
                    reason=(
                        "Image is unusually far from "
                        "the center of its visual cluster."
                    ),
                    value=float(distance),
                    threshold=distance_threshold,
                )
            )

        # -----------------------------------------
        # 8. Return result
        # -----------------------------------------

        return AnalysisResult(
            analyzer=self.name,
            images_checked=len(image_ids),
            findings=findings,
        )